-- Banco descartável, sem rede nem mensagens; desfaz todas as fixtures.
begin;
create temporary table d3 as select gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() c,gen_random_uuid() x,gen_random_uuid() y,gen_random_uuid() z,gen_random_uuid() alias,gen_random_uuid() person,gen_random_uuid() plan,gen_random_uuid() challenge,gen_random_uuid() grp,gen_random_uuid() attempt;
create function pg_temp.check_d3(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d3((select not enabled from public.whatsapp_distribution_policy),'Automação nasce desligada');
update public.whatsapp_send_controls set paused=false where scope='global';
update d3 set a=(public.register_my_barbershop(gen_random_uuid(),'Auto Alfa','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid,
 b=(public.register_my_barbershop(gen_random_uuid(),'Auto Beta','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select pg_temp.check_d3((select count(*)=2 from public.whatsapp_distribution_waiting,d3 where barbershop_id in(a,b) and reason='disabled'),'Cadastro completo permanece aguardando quando política desligada');
select public.platform_create_whatsapp_channel(x,'Auto A') from d3;
select public.platform_create_whatsapp_channel(y,'Auto B') from d3;
select public.platform_create_whatsapp_channel(z,'Auto C') from d3;
select public.platform_create_whatsapp_channel(alias,'Auto alias') from d3;
update public.whatsapp_channels set display_phone=case id when (select x from d3) then '+5511800000111' when (select y from d3) then '+5511800000222' when (select z from d3) then '+5511800000333' else '+5511800000111' end,status='open' where id in(select x from d3 union all select y from d3 union all select z from d3 union all select alias from d3);
select pg_temp.check_d3((select count(*)=0 from public.whatsapp_distribution_candidates()),'Pareamento sozinho não prova controle exclusivo da plataforma');
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select x from d3 union all select y from d3 union all select z from d3 union all select alias from d3);
select pg_temp.check_d3((select count(*)=3 from public.whatsapp_distribution_candidates()),'Dois IDs do mesmo telefone não viram dois candidatos');
select public.platform_plan_whatsapp_distribution(plan,array[a,b],false) from d3;
select pg_temp.check_d3((select jsonb_array_length(assignments)=2 and jsonb_array_length(blocked)=0 from public.whatsapp_distribution_plans,d3 where id=d3.plan),'Proposta persistente cobre o lote com dois números distintos e terceira reserva');
select pg_temp.check_d3((select count(distinct e->>'primary')=2 from public.whatsapp_distribution_plans p,d3,jsonb_array_elements(p.assignments) e where p.id=d3.plan),'Lote considera carga projetada em cada nova barbearia');
select pg_temp.check_d3((select count(*)=0 from public.whatsapp_number_links,d3 where barbershop_id in(a,b)),'Gerar proposta não muda configurações');
select public.platform_apply_whatsapp_distribution(plan) from d3;
select pg_temp.check_d3((select count(*)=2 and bool_and(not enabled and backup_channel_id is not null and backup2_channel_id is not null) from public.whatsapp_number_links,d3 where barbershop_id in(a,b)),'Aplicação persiste três posições sem ligar mensagens');
select public.platform_apply_whatsapp_distribution(plan) from d3;
select pg_temp.check_d3((select count(*)=2 from public.whatsapp_number_links,d3 where barbershop_id in(a,b)),'Repetição da aplicação devolve resultado sem duplicar');
select public.platform_set_whatsapp_automatic(true,1);
update d3 set c=(public.register_my_barbershop(gen_random_uuid(),'Auto Gama','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select pg_temp.check_d3((select count(*)=1 from public.whatsapp_number_links,d3 where barbershop_id=c),'Cadastro cria atribuição automática no servidor sem navegador');
select public.run_whatsapp_distribution();
select pg_temp.check_d3((select count(*)=3 from public.whatsapp_number_links,d3 where barbershop_id in(a,b,c)),'Rodada automática preserva configurações já existentes');
update d3 set plan=gen_random_uuid();
select public.platform_plan_whatsapp_distribution(plan,array[a],true) from d3;
update public.whatsapp_channels set status='disconnected' where id=(select y from d3);
do $$begin begin perform public.platform_apply_whatsapp_distribution((select plan from d3));raise exception 'FAIL: plano desatualizado aplicado';exception when serialization_failure then raise notice 'PASS: mudança de conexão invalida plano antes de aplicar';end;end $$;
update public.whatsapp_channels set status='open' where id=(select y from d3);
update d3 set plan=gen_random_uuid();
select public.platform_plan_whatsapp_distribution(plan,array[a],true) from d3;
update public.whatsapp_distribution_plans set expires_at=now()-interval '1 second' where id=(select plan from d3);
do $$begin begin perform public.platform_apply_whatsapp_distribution((select plan from d3));raise exception 'FAIL: plano expirado aplicado';exception when serialization_failure then raise notice 'PASS: plano expirado não aplica';end;end $$;
update public.whatsapp_channels set connection_observed_at=now()-interval '3 minutes' where id in(select x from d3 union all select y from d3 union all select z from d3 union all select alias from d3);
select pg_temp.check_d3((select count(*)=0 from public.whatsapp_distribution_candidates()),'Status conectado antigo não autoriza atribuição automática');
update d3 set c=(public.register_my_barbershop(gen_random_uuid(),'Sem par','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select pg_temp.check_d3((select public.whatsapp_complete_shop(c) and not exists(select 1 from public.whatsapp_number_links where barbershop_id=c) from d3),'Falta de par não desfaz cadastro da loja');
select pg_temp.check_d3((select reason='no_pair' from public.whatsapp_distribution_waiting,d3 where barbershop_id=c),'Barbearia sem par fica sinalizada para próxima rodada');
select pg_temp.check_d3((select not public.record_whatsapp_distribution_connection(x,'bc-'||x,'+5511800000111',1,'open','+5511800000999') from d3),'Observação de outro telefone não confirma identidade da plataforma');
select public.record_whatsapp_distribution_connection(id,instance_name,display_phone,routing_version,'open',display_phone) from public.whatsapp_channels where id in(select x from d3 union all select y from d3 union all select z from d3 union all select alias from d3);
select public.record_whatsapp_distribution_connection(x,'bc-'||x,'+5511800000111',1,'unknown',null) from d3;
select pg_temp.check_d3((select connection_observed_at is null and status='open' from public.whatsapp_channels,d3 where id=x),'Estado desconhecido invalida frescura sem inventar desconexão');
select public.record_whatsapp_distribution_connection(id,instance_name,display_phone,routing_version,'open',display_phone) from public.whatsapp_channels where id=(select x from d3);
select public.run_whatsapp_distribution();
select pg_temp.check_d3((select count(*)=1 from public.whatsapp_number_links,d3 where barbershop_id=c),'Rodada posterior cobre loja aguardando depois de confirmar conexão');
-- Restrição acompanha telefone; reconectar/excluir pausa não apaga necessidade de revisão.
select public.set_whatsapp_send_pause(x::text,true,'restriction',0) from d3;
select pg_temp.check_d3((select public.whatsapp_number_restricted(alias) from d3),'Restrição física bloqueia alias');
select public.set_whatsapp_send_pause(x::text,false,'resumed',1) from d3;
select pg_temp.check_d3((select public.whatsapp_number_restricted(alias) from d3),'Retomar pausa comum não equivale à revisão da restrição');
do $$begin
 begin perform public.platform_review_whatsapp_phone('5511800000111',1,'reviewed_in_app','teste-local',false);raise exception 'FAIL: sem confirmação';exception when invalid_parameter_value then raise notice 'PASS: revisão exige confirmação explícita';end;
 begin perform public.platform_review_whatsapp_phone('5511800000111',0,'reviewed_in_app','teste-local',true);raise exception 'FAIL: versão antiga';exception when serialization_failure then raise notice 'PASS: revisão concorrente exige versão atual';end;
end $$;
select public.platform_review_whatsapp_phone('5511800000111',1,'reviewed_in_app','teste-local',true);
select pg_temp.check_d3((select not public.whatsapp_number_restricted(alias) from d3),'Revisão com evidência libera somente a barreira histórica');
select public.set_whatsapp_send_pause(x::text,true,'restriction',2) from d3;
select pg_temp.check_d3((select public.whatsapp_number_restricted(alias) from d3),'Nova restrição posterior revoga revisão anterior');
select pg_temp.check_d3((select count(*)=3 from public.whatsapp_phone_review_history where phone='5511800000111'),'Evidências anteriores ficam preservadas');
-- Métricas comprovadas e correção tardia: somente este grupo e identidade.
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d3;
insert into public.whatsapp_care_groups(id,barbershop_id,customer_id,customer_phone,group_jid) select grp,a,person,'+5511999999999','777777-88888@g.us' from d3;
insert into public.auth_otp_challenges(id,user_id,channel,destination,code_hash,purpose,expires_at) select challenge,person,'whatsapp','+5511999999999',repeat('a',64),'verify_phone',now()+interval '10 minutes' from d3;
insert into public.whatsapp_group_login_routes(challenge_id,group_id,version,instance_name) select challenge,grp,1,'bc-'||z from d3;
update public.whatsapp_activity_identity set observed_since=now()-interval '2 days' where channel_id=(select z from d3);
insert into public.whatsapp_send_attempts(id,challenge_id,instance_name,state,started_at) select attempt,challenge,'bc-'||z,'unknown',now()-interval '10 minutes' from d3;
select pg_temp.check_d3((select public.platform_whatsapp_number_activity()->z::text->>'uncertain'='1' from d3),'Resultado incerto de grupo entra uma vez no perfil');
select public.finish_whatsapp_send(attempt,'recibo-ficticio') from d3;
select public.finish_whatsapp_send(attempt,'recibo-ficticio') from d3;
select pg_temp.check_d3((select public.platform_whatsapp_number_activity()->z::text->>'accepted'='1' and public.platform_whatsapp_number_activity()->z::text->>'uncertain'='0' from d3),'Comprovante tardio corrige incerto sem duplicar aceites');
delete from public.whatsapp_send_attempts where id=(select attempt from d3);
select pg_temp.check_d3((select public.platform_whatsapp_number_activity()->z::text->>'accepted'='1' from d3),'Expurgo do diário não apaga o total observado');
select pg_temp.check_d3(not has_function_privilege('authenticated','public.whatsapp_distribution_candidates()','execute'),'Cliente não enumera candidatos internos');
select pg_temp.check_d3(not has_function_privilege('anon','public.platform_apply_whatsapp_distribution(uuid)','execute'),'Anônimo não aplica plano');
select pg_temp.check_d3(not has_function_privilege('authenticated','public.run_whatsapp_distribution()','execute'),'Agendador restrito ao serviço');
select pg_temp.check_d3(not has_table_privilege('authenticated','public.whatsapp_phone_review_history','select'),'Histórico de revisão privado');
rollback;
